  static String categoryIcon(String category) {
    switch (category) {
      case 'Sarees':
        return 'saree';
      case 'Dress Materials':
        return 'dress';
      case 'Saree Borders':
        return 'border';
      case 'T-Shirts':
        return 'tshirt';
      case 'Mugs':
        return 'mug';
      case 'Posters':
        return 'poster';
      case 'Embroidery':
        return 'embroidery';
      case 'Cardboard':
        return 'cardboard';
      case 'Glass Art':
        return 'glass';
      default:
        return 'tshirt';
    }
  }

