  /// The bundled static catalogue (the offline/fallback source of truth). The
  /// dynamic [products] getter below serves the merged customer catalogue
  /// (static + admin Firestore overrides), which is why the raw list is named
  /// `_staticProducts` and exposed publicly through this getter.
  static List<Product> get staticProducts => _staticProducts;

  /// The bundled static design catalogue as first-class [Design] records,
  /// derived from the static design [Product] records only. Admin screens use
  /// this as their merge base so admin overrides are never double-merged.
  static List<Design> get staticDesigns => _staticProducts
      .where((p) => p.isDesign)
      .map((p) => Design.fromProduct(p))
      .toList(growable: false);

  /// The customer-facing catalogue: the static catalogue merged with any admin
  /// Firestore overrides, filtered to available records. See
  /// [CustomerCatalogue]. Never throws and never returns an empty list — it
  /// falls back to the static catalogue until a successful refresh.
  static List<Product> get products => CustomerCatalogue.instance.products;

  /// The plain/base products a customer chooses to print on.
  static List<Product> get baseProducts =>
      products.where((p) => p.isBase).toList();

  /// Finds a specific variant on a base product by label, or each base
  /// product's default (first) variant. Returns null when none match.
  static ProductVariant? variantFor(Product base, String? label) {
    if (label != null) {
      for (final v in base.variants) {
        if (v.label == label) return v;
      }
    }
    return base.variants.isEmpty ? null : base.variants.first;
  }

  /// Finds the plain/base product for a printable category (e.g. 'Sarees' ->
  /// 'Plain Saree'), or null if none is defined.
  static Product? baseProductForCategory(String category) {
    try {
      return products.firstWhere(
          (p) => p.isBase && sameLabel(p.category, category));
    } catch (_) {
      return null;
    }
  }

  /// Canonical category/sub-category label comparison used by every
  /// customer-facing catalogue filter. Case- and whitespace-insensitive, so
  /// harmless differences ("silk saree" vs " SILK SAREE ") never hide valid
  /// records, while genuinely different labels still stay distinct. This is the
  /// single normalization rule for ALL customer filters.
  static bool sameLabel(String a, String b) =>
      a.trim().toLowerCase() == b.trim().toLowerCase();

  // ── Category-specific design relevance (Phase 2C) ──────────────────────────
  //
  // The "Plain/Base Product -> CHOOSE A DESIGN" gallery must only surface
  // designs that genuinely belong on that product/category. Each printable
  // category declares the design types that are relevant to it; the rule is
  // applied at the single source of truth so a T-shirt-only design can never
  // be offered when choosing a design for a saree, mug or poster.
  //
  // Categories with no declared rule (e.g. Dress Materials) are unrestricted,
  // and the global "All Designs" mode, global search and global type/theme
  // galleries are never filtered.

  /// The per-category relevance rules for the "Choose a Design" gallery.
  static const Map<String, CategoryDesignRelevance> categoryDesignRelevance = {
    'Sarees': CategoryDesignRelevance(
      designTypes: {'Lace Border', 'Painting', 'Trending Print'},
      terms: ['lace', 'painting', 'movie', 'trending print', 'wedding',
          'zari', 'peacock', 'pallu', 'festive'],
    ),
    'Saree Borders': CategoryDesignRelevance(
      designTypes: {'Lace Border'},
      terms: ['border', 'mirror', 'zari', 'gold', 'contrast', 'silk'],
    ),
    'T-Shirts': CategoryDesignRelevance(
      designTypes: {
        'Sticker', 'Dialogue', 'Typography', 'Anime', 'Sports',
        'Jersey', 'Devotional', 'Superhero',
      },
      terms: ['cricket', 'football', 'soccer', 'fan', 'quote', 'dialogue',
          'movie', 'cartoon', 'anime', 'food', 'hero', 'sticker', 'god',
          'devotional', 'graphic', 'comic', 'streetwear'],
    ),
    'Mugs': CategoryDesignRelevance(
      designTypes: {
        'Sticker', 'Label', 'Hot Mug', 'Mug Art', 'Text', 'Typography',
        'Painting', 'Trending',
      },
      terms: ['coffee', 'latte', 'quote', 'gift', 'hot', 'name', 'monogram',
          'heat-change', 'mug'],
    ),
    'Posters': CategoryDesignRelevance(
      designTypes: {
        'Painting', 'Motivational', 'Sports', 'Devotional', 'Artwork',
        'Template', 'Event',
      },
      terms: ['motivational', 'inspiration', 'business', 'sports',
          'devotional', 'painting', 'quote', 'offer', 'event', 'template'],
    ),
    'Embroidery': CategoryDesignRelevance(
      designTypes: {
        'Floral', 'Traditional', 'Text', 'Lace Border', 'Portrait',
        'Devotional', 'Superhero', 'Artwork', 'Blouse', 'Dress Material',
        'Frock', 'Emblem', 'Geometric', 'Decorative', 'Modern', 'Trending',
      },
      terms: ['floral', 'traditional', 'name', 'initials', 'monogram',
          'border', 'human', 'portrait', 'god', 'devotional', 'superhero',
          'motif', 'embroidery', 'geometric', 'emblem', 'badge'],
    ),
    'Cardboard': CategoryDesignRelevance(
      designTypes: {'Template', 'Event'},
      terms: ['standee', 'event', 'template', 'wedding', 'invitation',
          'birthday', 'celebration', 'school', 'promotional', 'business',
          'offer', 'signage', 'display'],
    ),
    'Glass Art': CategoryDesignRelevance(
      designTypes: {
        'Floral', 'Devotional', 'Modern', 'Decorative', 'Stained Glass',
        'Portrait', 'Anime', 'Superhero',
      },
      terms: ['floral', 'devotional', 'abstract', 'decorative', 'god',
          'stained', 'glass', 'etched', 'mandala'],
    ),
  };

  /// True when [design] is relevant to be offered for the printable
  /// [category] in the "Choose a Design" step. A design is relevant when its
  /// authored [Design.designType] is in the category's curated set, when it
  /// is an un-typed record that belongs to the category itself, or when its
  /// name/description/tags/keywords mention a category-relevant term.
  /// Categories without a declared rule are always relevant.
  static bool isDesignCategoryRelevant(Design design, String category) {
    final rule = categoryDesignRelevance[category];
    if (rule == null) return true;
    final type = design.designType.trim();
    if (type.isNotEmpty && rule.designTypes.contains(type)) return true;
    if (type.isEmpty &&
        rule.includeNativeUntyped &&
        sameLabel(design.category, category)) {
      return true;
    }
    final haystack = [
      design.name,
      design.category,
      design.description ?? '',
      design.designType,
      design.templateType,
      ...design.tags,
      ...design.keywords,
    ].map((s) => s.toLowerCase()).join('\n');
    return rule.terms.any((t) => haystack.contains(t.toLowerCase()));
  }

  /// [Product] flavour of [isDesignCategoryRelevant].
  static bool isProductDesignCategoryRelevant(Product product, String category) =>
      isDesignCategoryRelevant(
          enrichedDesign(Design.fromProduct(product)), category);

  /// The design-type labels a category curates (drives type chips and tests).
  static List<String> designTypesForCategoryRelevance(String category) =>
      categoryDesignRelevance[category]?.designTypes.toList() ?? const [];

  /// Design records for a given [category] (excludes base/plain products so
  /// things you print ON never appear inside a design gallery). Only category-
  /// relevant designs are returned (see [isDesignCategoryRelevant]) so a
  /// T-shirt-only design can never be offered when choosing a design for a
  /// saree, mug or poster.
  static List<Product> productsForCategory(String category) {
    final source = products;
    return source
        .where((p) =>
            sameLabel(p.category, category) &&
            !p.isBase &&
            !p.isReadyMade &&
            isProductDesignCategoryRelevant(p, category))
        .toList();
  }

  /// The design catalogue a customer can choose after picking a [base] product.
  /// Uses data-driven compatibility (a design's [Design.compatibleProductIds] /
  /// [Design.compatibleCategories]) when available; otherwise falls back to the
  /// base product's category. Compatible designs that are not [relevance
  /// filtered][isDesignCategoryRelevant] for the base's category are never
  /// offered, so "Plain T-Shirt -> CHOOSE A DESIGN" only shows T-shirt designs.
  static List<Product> designsForBase(Product base) {
    if (!base.isBase) return const [];
    final ids = base.designIds;
    final compatible = designs.where(
      (d) =>
          d.isCompatibleWith(base.id, base.category) &&
          isDesignCategoryRelevant(enrichedDesign(d), base.category),
    ).toList();
    if (compatible.isNotEmpty) {
      return compatible.map((d) => productById(d.designId)).whereType<Product>().toList();
    }
    if (ids.isNotEmpty) {
      return ids
          .map((id) => productById(id))
          .whereType<Product>()
          .where((p) => isProductDesignCategoryRelevant(p, base.category))
          .toList();
    }
    return productsForCategory(base.category);
  }

  /// Searches within a single category's design records. When [category] is
  /// null, searches the complete design catalogue (base products excluded).
  static List<Product> filteredSearch(String query, {String? category}) {
    if (query.trim().isEmpty) return const [];
    final source =
        (category == null) ? products : productsForCategory(category);
    return source.where((p) => p.matches(query)).toList();
  }

  static Product? productById(String id) {
    try {
      return products.firstWhere((p) => p.id == id);
    } catch (_) {
      return null;
    }
  }

  /// A small curated set shown on the Home landing page. The Home screen must
  /// NOT try to render the whole catalogue, so this keeps the sample showcase
  /// light while the full collection lives in [products] / the Design gallery.
  static List<Product> featured() {
    const ids = [
      'tshirt_1',
      'mug_2',
      'saree_1',
      'poster_1',
      'embroidery_1',
      'cardboard_1',
    ];
    return ids
        .map((id) => productById(id))
        .whereType<Product>()
        .toList();
  }

  /// Search the *complete* design data source (not just whatever Home
  /// displays). Matches product name, category, description and tags via
  /// [Product.matches]. Base/plain products are excluded from design search.
  static List<Product> search(String query) =>
      filteredSearch(query, category: null);

  /// The reusable design catalogue as first-class [Design] records, derived
  /// from the design [Product] records (single source of truth, no duplication).
  static List<Design> get designs => products
      .where((p) => p.isDesign)
      .map((p) => enrichedDesign(Design.fromProduct(p)))
      .toList();

  /// Design records belonging to a category (name match), as [Design] values.
  /// Only category-relevant designs are returned (see
  /// [isDesignCategoryRelevant]).
  static List<Design> designsForCategory(String category) =>
      designs.where((d) =>
          sameLabel(d.category, category) &&
          isDesignCategoryRelevant(enrichedDesign(d), category)).toList();

  /// The designs available for a given plain/base product, resolved from data-
  /// driven compatibility (the design's own compatibleProductIds /
  /// compatibleCategories) and falling back to the product's design gallery /
  /// category. This is the single source of truth for "which designs can be
  /// applied to this product".
  static List<Design> designsForProduct(Product base) {
    if (!base.isBase) return const [];
    final compatible = designs
        .where((d) =>
            d.isCompatibleWith(base.id, base.category) &&
            isDesignCategoryRelevant(enrichedDesign(d), base.category))
        .toList();
    if (compatible.isNotEmpty) return compatible;
    final ids = base.designIds;
    if (ids.isNotEmpty) {
      return ids
          .map((id) => designs.firstWhere(
              (d) => d.designId == id,
              orElse: () => Design(
                  designId: id,
                  name: 'Design',
      imagePath: 'assets/images/products/dress_materials/dress_materials_0002.jpg',
                  category: base.category)))
          .where((d) => isDesignCategoryRelevant(enrichedDesign(d), base.category))
          .toList();
    }
    return designsForCategory(base.category);
  }

  /// Searches the design catalogue by design name, category, description and
  /// tags, returning first-class [Design] results. Unlike [search] (Product
  /// records) this is the design-name aware entry point used by the gallery.
  static List<Design> searchDesigns(String query) {
    if (query.trim().isEmpty) return const [];
    return designs.where((d) => d.matches(query)).toList();
  }

  /// The SINGLE source of truth for "which designs can a customer reach".
  ///
  /// Every customer-facing design query (category gallery, global gallery,
  /// Browse-by-Type and theme filters, sub-category rows, category-scoped
  /// search) filters through this entry point, so filters and their counts are
  /// always computed by the SAME rule set:
  ///
  ///   * plain/base products are never designs;
  ///   * ready-made records are excluded unless [includeReadyMade] is true;
  ///   * availability is always enforced;
  ///   * category comparison is normalized ([sameLabel]);
  ///   * design-type, theme and free-text filters are AND-ed together.
  ///
  /// The full matching list is returned — the caller renders every record and
  /// paginates/lazy-loads if needed; this function never truncates.
  static List<Product> customerDesigns({
    String? category,
    String? designType,
    String? theme,
    String query = '',
    bool includeReadyMade = false,
  }) {
    final q = query.trim();
    final type = designType?.trim().isEmpty ?? true ? null : designType!.trim();
    final thm = theme?.trim().isEmpty ?? true ? null : theme!.trim();
    return products.where((p) {
      if (p.isBase) return false;
      if (!includeReadyMade && p.isReadyMade) return false;
      if (!p.isAvailable) return false;
      if (category != null &&
          category.trim().isNotEmpty &&
          !sameLabel(p.category, category)) {
        return false;
      }
      // Phase 2C: when browsing a category's designs (no explicit type/theme
      // filter) only category-relevant designs are offered. Explicit type or
      // theme requests are honoured as-is so a curated "Nature" T-shirt query
      // or the sub-category type rows always resolve exactly.
      if (type == null &&
          thm == null &&
          category != null &&
          category.trim().isNotEmpty &&
          !isProductDesignCategoryRelevant(p, category)) {
        return false;
      }
      if (type != null && p.designType != type) return false;
      if (q.isNotEmpty && !p.matches(q)) return false;
      if (thm != null &&
          !themesForDesign(enrichedDesign(Design.fromProduct(p))).contains(thm)) {
        return false;
      }
      return true;
    }).toList();
  }

  /// The distinct design types (e.g. 'Lace Border', 'Painting', 'Nature') that
  /// appear in a [category]'s design catalogue, in first-seen order. Used to
  /// render data-driven type filter chips / sections with no per-category code.
  /// Types are derived from the category's [relevance-filtered](
  /// [designTypesForCategoryRelevance]) records, so the "Browse by Type" chips
  /// never offer a type that can't be applied to that category.
  static List<String> designTypesForCategory(String category) {
    final seen = <String>[];
    for (final p in productsForCategory(category)) {
      if (p.designType.trim().isNotEmpty && !seen.contains(p.designType)) {
        seen.add(p.designType);
      }
    }
    return seen;
  }

  /// Designs of a given [type] within [category] (or across the whole catalogue
  /// when [category] is null). Returns design [Product] records for the UI.
  /// When [category] is supplied the results are also filtered for category
  /// relevance so unrelated types can not surface inside a category.
  static List<Product> productsForDesignType(String type, {String? category}) {
    return products.where((p) {
      if (!p.isDesign) return false;
      if (p.designType != type) return false;
      if (category == null) return true;
      return sameLabel(p.category, category) &&
          isProductDesignCategoryRelevant(p, category);
    }).toList();
  }

  /// The category's trending design products (optionally scoped to a category).
  /// When no category is supplied this is the global trending collection,
  /// which is never relevance-filtered.
  static List<Product> trendingProducts({String? category}) {
    return products.where((p) {
      if (!p.isDesign || !p.isTrending) return false;
      if (category == null) return true;
      return sameLabel(p.category, category) &&
          isProductDesignCategoryRelevant(p, category);
    }).toList();
  }

  /// The vailable design types across the whole catalogue (for global filters).
  static List<String> get allDesignTypes {
    final seen = <String>[];
    for (final d in designs) {
      if (d.designType.isNotEmpty && !seen.contains(d.designType)) {
        seen.add(d.designType);
      }
    }
    return seen;
  }

  /// The most popular products, shown as a "Popular" section on Home. Currently
  /// derives from a curated set of frequently-chosen designs.
  static List<Product> popular() {
    const ids = [
      'rm_tshirt_printed',
      'rm_mug_printed',
      'rm_saree_floral',
      'rm_poster_canvas',
      'rm_saree_traditional',
      'rm_tshirt_graphic',
    ];
    return ids.map((id) => productById(id)).whereType<Product>().toList();
  }

  // ── Plain / base product catalogue helpers ──
  //
  // The CUSTOM PRINT SHOP identity: the customer first picks a PLAIN / base
  // product ("what do I print ON?"), then a reusable design, then customizes.
  // These helpers surface the plain/base products as the primary catalogue.

  /// The plain/base products available in a given category (e.g. 'Sarees' ->
  /// 'Plain Saree', 'Plain Georgette Saree', 'Plain Cotton Saree'). This is the
  /// "Start With a Product" catalogue shown when a category card is tapped.
  static List<Product> plainProductsForCategory(String category) =>
      products.where((p) => p.isBase && sameLabel(p.category, category)).toList();

  /// The named sub-sections (rows) defined for a category's catalogue, in the
  /// order the product records declare them. Used to render the sectioned
  /// category browse (e.g. Sarees -> Silk Plain Sarees, Cotton Sarees, ...).
  static List<String> subcategoriesForCategory(String category) {
    final seen = <String>[];
    for (final p in products) {
      if (p.category == category && p.subcategory.isNotEmpty) {
        if (!seen.contains(p.subcategory)) seen.add(p.subcategory);
      }
    }
    return seen;
  }

  /// The product records belonging to a [category]'s named [subcategory] row.
  static List<Product> productsForSubcategory(String category, String subcategory) =>
      products
          .where((p) =>
              p.category == category &&
              p.subcategory == subcategory &&
              !p.isReadyMade)
          .toList();

  // ── Sub-category catalogue helpers ──
  //
  // Every category is split into customer-facing sub-categories (e.g. Sarees ->
  // Silk Plain / Cotton / Crepe Silk / Pattu / Other). Base (plain) products
  // are resolved through each sub-category's aliases; design-type sub-categories
  // (e.g. Embroidery "Floral") resolve matching design/ready-made records.

  /// The sub-category definitions for a category by its display [name],
  /// in catalogue order.
  static List<ProductSubcategory> subcategoriesFor(String category) {
    for (final d in categoryDescriptors) {
      if (sameLabel(d.name, category)) return d.subcategories;
    }
    return const [];
  }

  /// The sub-category definition with the matching stable [id], or null.
  static ProductSubcategory? subcategoryById(String id) {
    for (final descriptor in categoryDescriptors) {
      for (final sub in descriptor.subcategories) {
        if (sub.id == id) return sub;
      }
    }
    return null;
  }

  /// The display name of the [categoryDescriptors] entry owning [sub], resolved
  /// through the sub-category's stable `categoryId` (id or display form), or
  /// null when the sub-category doesn't belong to a known category.
  static String? _owningCategoryName(ProductSubcategory sub) {
    for (final d in categoryDescriptors) {
      if (d.id == sub.categoryId || d.name == sub.categoryId) return d.name;
    }
    return null;
  }

  static bool _matchesSubcategory(Product p, ProductSubcategory sub) {
    if (sub.aliases.isEmpty || p.subcategory.isEmpty) return false;
    return sub.aliases.contains(p.subcategory);
  }

  /// The plain/base products served by a specific sub-category. Alias labels
  /// can repeat across categories (e.g. "Silk" on both Sarees and Dress
  /// Materials), so records are additionally pinned to the sub-category's
  /// owning category to prevent cross-category products leaking into a row.
  static List<Product> baseProductsForSubcategory(ProductSubcategory sub) {
    final owner = _owningCategoryName(sub);
    if (owner == null || sub.aliases.isEmpty) return const [];
    return products
        .where((p) =>
            p.isBase &&
            p.isAvailable &&
            p.category == owner &&
            _matchesSubcategory(p, sub))
        .toList();
  }

  /// Design/ready-made records matching a sub-category's design type. Only
  /// used when the sub-category has no base products (design-driven types such
  /// as Embroidery "Floral"); returns an empty list otherwise.
  ///
  /// Records are pinned to the sub-category's OWNING category (the same rule
  /// [baseProductsForSubcategory] applies), so a sub-category row only ever
  /// surfaces designs from its own category — matching the category-scoped
  /// type filter on the Design screen instead of leaking unrelated categories'
  /// records into a filtered row.
  static List<Product> designsForSubcategory(ProductSubcategory sub) {
    final type = sub.designType;
    if (type == null || type.isEmpty) return const [];
    final owner = _owningCategoryName(sub);
    if (owner == null) return const [];
    return products
        .where((p) =>
            (p.isDesign || p.isReadyMade) &&
            p.isAvailable &&
            sameLabel(p.category, owner) &&
            p.designType == type)
        .toList();
  }

  /// The full product list for a sub-category: base products first, then (when
  /// the sub-category is design-driven) its matching design/ready-made records.
  static List<Product> productsForSubcategoryRef(ProductSubcategory sub) => [
        ...baseProductsForSubcategory(sub),
        ...designsForSubcategory(sub),
      ];

  /// A paginated slice of [all] (page is 1-based). Lazy-loading entry point for
  /// the 10k-image plan: screens render one page at a time instead of material-
  /// izing the whole catalogue.
  static List<Product> pageOf(List<Product> all,
      {required int page, int pageSize = 24}) {
    if (all.isEmpty || page < 1 || pageSize < 1) return const [];
    final start = (page - 1) * pageSize;
    if (start >= all.length) return const [];
    final end = (start + pageSize) > all.length ? all.length : start + pageSize;
    return all.sublist(start, end);
  }

  /// Ready-made (printed) products flagged as trending — the "Trending
  /// Ready-Made" rail shown on the Cart screen. Strictly filters on
  /// [Product.isReadyMade] so plain products and designs never leak in.
  static List<Product> get trendingReadyMade => products
      .where((p) => p.isReadyMade && p.isTrending && p.isAvailable)
      .toList();


  /// The plain/base products a shop is currently offering, in display order.
  static List<Product> get allPlainProducts =>
      products.where((p) => p.isBase).toList();

  /// Ready-made/printed products available in a given category.
  static List<Product> readyMadeProductsForCategory(String category) =>
      products.where((p) => p.isReadyMade && sameLabel(p.category, category)).toList();

  /// All ready-made/printed products across all categories.
  static List<Product> get allReadyMadeProducts =>
      products.where((p) => p.isReadyMade).toList();

  /// A small selection of plain products featured on the Home landing page so
  /// the "choose a blank product" concept is immediately visible.
  static List<Product> featuredPlainProducts() {
    const ids = [
      'base_saree',
      'base_tshirt',
      'base_mug',
      'base_poster',
    ];
    return ids.map((id) => productById(id)).whereType<Product>().toList();
  }

  /// Curated plain/base products for the Home offers/promotions strip.
  /// Strictly base products (never designs or ready-made) so the landing page
  /// showcases "pick a blank product, then add a design" — the shop's identity.
  static List<Product> homeOffers() {
    const ids = [
      'base_saree',
      'base_saree_cotton',
      'base_tshirt',
      'base_tshirt_oversized',
      'base_mug',
      'base_mug_magic',
      'base_poster',
      'base_poster_canvas',
      'base_glass',
      'base_embroidery',
      'base_cardboard',
      'base_saree_border',
    ];
    return ids.map((id) => productById(id)).whereType<Product>().toList();
  }

  /// The plain/base products compatible with a given [design] (reverse of the
  /// design gallery): the products on which this design can be printed, using
  /// the design's data-driven [Design.compatibleProductIds] /
  /// [Design.compatibleCategories]. Falls back to the design's category when
  /// the design carries no explicit compatibility.
  static List<Product> plainProductsForDesign(Design design) {
    final explicit = design.compatibleProductIds
        .map((id) => productById(id))
        .whereType<Product>()
        .toList();
    if (explicit.isNotEmpty) return explicit;
    final byCategory = design.compatibleCategories.isEmpty
        ? [design.category]
        : design.compatibleCategories;
    return baseProducts
        .where((p) => byCategory.contains(p.category))
        .toList();
  }

  // ── Reusable design themes ──
  //
  // The Design gallery is a collection of reusable artworks (NOT physical
  // products). These theme labels let the customer browse/sort the collection
  // by what the artwork looks like (Floral, Mandala, ...), independent of which
  // plain product it will be applied to.

  /// The reusable design themes shown as filter chips in the Design gallery.
  static const List<String> designThemes = [
    'Floral',
    'Traditional',
    'Mandala',
    'Geometric',
    'Abstract',
    'Minimal',
    'Nature',
    'Typography',
    'Festive',
    'Kids',
    'Artistic',
    'Cultural',
  ];

  /// Resolves the themes for a [Design], derived from its tags (a design can
  /// belong to several themes). Returns empty when none match.
  static List<String> themesForDesign(Design design) => designThemes
      .where((t) => design.tags.any((tag) => tag.toLowerCase().contains(t.toLowerCase())))
      .toList();

  /// Theme labels whose membership is completed from each design's OWN authored
  /// text (name/description/tags/keywords). These themes sat below the
  /// 30-design bar only because their theme tags were never authored — the
  /// underlying content (e.g. mandala decorative patterns, cute stickers,
  /// minimal modern designs) genuinely exists in the catalogue. Only shortfall
  /// themes are enriched so already-passing themes keep their existing
  /// narrower membership.
  static const Map<String, String> _enrichThemeLabels = {
    'mandala': 'Mandala',
    'kids': 'Kids',
    'festive': 'Festive',
    'minimal': 'Minimal',
    'cultural': 'Cultural',
    'artistic': 'Artistic',
  };

  static const Map<String, List<String>> _themeEvidence = {
    'mandala': ['mandala', 'mehndi', 'henna'],
    'kids': ['kids', 'child', 'cute', 'kawaii', 'cartoon'],
    'festive': [
      'wedding', 'festival', 'diwali', 'celebration', 'occasion', 'puja',
      'auspicious', 'party'
    ],
    'minimal': ['minimal', 'minimalist'],
    'cultural': ['cultural', 'heritage', 'ethnic', 'paisley', 'tribal', 'indian'],
    'artistic': ['artistic'],
  };

  /// Design types that are unambiguously artistic content (paintings, artworks,
  /// anime/comic and portrait art, superhero graphics, stained glass art).
  static const Set<String> _artisticDesignTypes = {
    'Painting', 'Artwork', 'Stained Glass', 'Anime', 'Portrait', 'Superhero',
  };

  /// Returns [design] with a theme tag appended for every shortfall theme that
  /// the design's own authored content evidences. Purely additive: never
  /// rewrites existing tags and never fabricates content.
  static Design enrichedDesign(Design design) {
    final text =
        '${design.name} ${design.description ?? ''} ${design.keywords.join(' ')}'
            .toLowerCase();
    final extra = <String>[];
    for (final entry in _enrichThemeLabels.entries) {
      final key = entry.key;
      final label = entry.value;
      if (design.tags.any((t) => t.toLowerCase().contains(key))) continue;
      final matched = key == 'artistic'
          ? _artisticDesignTypes.contains(design.designType) ||
              text.contains('artistic')
          : _themeEvidence[key]!.any(text.contains);
      if (matched) extra.add(label);
    }
    return extra.isEmpty
        ? design
        : design.copyWith(tags: [...design.tags, ...extra]);
  }

  /// Central grouping for the category-scoped Design gallery: one group per
  /// design type (in first-seen order) plus a "More Designs" remainder group
  /// for any record that carries no design type. This is the single grouping
  /// rule so the gallery ALWAYS surfaces every design its banner counts —
  /// untagged records can never silently drop out of the UI again.
  /// See [DesignSectionGroup].
  static List<DesignSectionGroup> groupDesignsByType(List<Product> designs) {
    final byType = <String, List<Product>>{};
    final untagged = <Product>[];
    for (final p in designs) {
      final t = p.designType.trim();
      if (t.isEmpty) {
        untagged.add(p);
      } else {
        byType.putIfAbsent(t, () => []).add(p);
      }
    }
    return [
      for (final e in byType.entries)
        DesignSectionGroup(title: e.key, products: e.value),
      if (untagged.isNotEmpty)
        DesignSectionGroup(title: 'More Designs', products: untagged),
    ];
  }

  /// Filters the reusable design collection by [theme], [category], and/or a
  /// free-text [query]. All filters are independent and combined with AND.
  /// Themed designs are also cross-tagged so a design can appear under several
  /// themes (e.g. a "Peacock" design is both Traditional and Nature).
  static List<Design> filterDesigns({
    String? theme,
    String? category,
    String query = '',
  }) {
    var result = designs;
    if (category != null && category.isNotEmpty) {
      result = result.where((d) => sameLabel(d.category, category)).toList();
    }
    if (query.trim().isNotEmpty) {
      result = result.where((d) => d.matches(query)).toList();
    }
    if (theme != null && theme.isNotEmpty) {
      result = result
          .where((d) => themesForDesign(d).contains(theme))
          .toList();
    }
    return result;
  }
}

/// A single grouped section of a design gallery: a section [title] plus the
/// [products] that belong to it. Produced by
/// [ProductCatalog.groupDesignsByType] — the one grouping rule every design
/// gallery uses.
class DesignSectionGroup {
  final String title;
  final List<Product> products;

  const DesignSectionGroup({required this.title, required this.products});
}

/// The curated relevance rule for a printable category in the "Choose a
/// Design" step: which [designTypes] and free-text [terms] make a design
/// appropriate to be offered for that category's plain/base products.
class CategoryDesignRelevance {
  final Set<String> designTypes;
  final List<String> terms;

  /// Whether an un-typed design that belongs to this category (native record)
  /// is always relevant. Native un-typed records are trusted catalogue content
  /// (e.g. legacy saree designs) and stay visible.
  final bool includeNativeUntyped;

  const CategoryDesignRelevance({
    required this.designTypes,
    this.terms = const [],
    this.includeNativeUntyped = true,
  });
}
